# Put a person on hold, or take them off it. While held, their OPEN claims count in no live total.
validate:
  class: net.officefloor.hq.app.person.ValidateHold
  next: snapshot
# Keep the figures as they were, so the change can audit the ones it moves.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: hold
hold:
  class: net.officefloor.hq.app.person.HoldPerson
  govern: [ transaction ]
  next: record
# Audit only once the hold is saved.
record:
  class: net.officefloor.hq.app.person.RecordPersonHeld
  govern: [ transaction ]
  next: rollup
# After the change's own lines: a line per person whose figures moved, then the totals if they did.
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
# The sheet's people, in the order they were added.
respond:
  class: net.officefloor.hq.app.person.RespondWithPeople
  govern: [ readonly-transaction ]
-- A person can be put on hold and taken off it again. While held, their OPEN claims count in no
-- live total (their own claimed and due-total, the sheet's totals, a period's total); their
-- SETTLED claims still count.
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
-- The people on a sheet, listed in the order they were added (by id). `grade` is one of A, B, C.
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL,
    name     VARCHAR(500) NOT NULL,
    grade    VARCHAR(1)   NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
package net.officefloor.hq.app.person;

/** Body of a hold toggle: who makes the change. */
public record HoldRequest(String user) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateHold {
    public void validate(@RequestBody HoldRequest request, Out<Actor> actor) {
        actor.set(new Actor(request != null ? request.user() : null));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Puts the person on hold, or takes them off it when they are held. Read afresh and locked, so
 *  two toggles at once happen one after the other. Not an edit: the person's version is untouched,
 *  so an editor open on them can still save. Publishes the person as they are now. */
public class HoldPerson {
    public void hold(@PathVariable("sheetId") String sheetId, @PathVariable("personId") long personId,
            People people, Out<Person> personOut) throws PersonNotFoundException {
        Person person = people.lock(sheetId, personId);
        if (person == null) throw new PersonNotFoundException(personId);
        person.setHeld(!person.isHeld());
        people.saveHold(person);
        personOut.set(person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.plugin.variable.Val;

/** Runs after the hold is saved: PERSON_HELD when put on hold, PERSON_RELEASED when taken off. */
public class RecordPersonHeld {
    public void record(@Val Person person, @Val Actor actor, Audit audit) {
        audit.record((person.isHeld() ? "PERSON_HELD" : "PERSON_RELEASED") + " sheet=" + person.getSheetId()
                + " by=" + actor.user() + " name=" + person.getName());
    }
}
package net.officefloor.hq.app.person;

import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people of each sheet, kept in the order they were added. */
@Repository
public class People {

    private static final String COLUMNS = "SELECT id, sheet_id, name, grade, version, statement_count, stated_total, statement_date, retired_from, held FROM person";

    private final JdbcTemplate jdbc;

    public People(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Person> onSheet(String sheetId) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? ORDER BY id",
                People::person,
                sheetId);
    }

    /** The person with this id on this sheet, or null when there is none. */
    public Person find(String sheetId, long id) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND id = ?",
                People::person,
                sheetId, id).stream().findFirst().orElse(null);
    }

    /** The person with this id on this sheet, read afresh and locked for the rest of the
     *  transaction, so two statements for one person at once happen one after the other. */
    public Person lock(String sheetId, long id) {
